draw((0,0)--(1.08,1.87),linewidth(0.7));
draw(Circle((0.57,1),1),linewidth(0.7));
draw((0.57,1)--(0.57,0),linewidth(0.7));
draw((-1,1.73)--(0,0)--(2.15,0),linewidth(0.7));
label("$C$",(0.57,1),E);
label("$O$",(0,0),SW);
label("$B$",(-0.29,0.5),W);
label("$A$",(0.57,0),S);
label("$D$",(1.08,1.87),NE);
